package com.bank.router;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PaymentRouterDemo {
    private static final Logger log = Logger.getLogger(PaymentRouterDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"), AccountTier.HIGH);
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"), AccountTier.MID);

        PaymentRouterService router = new PaymentRouterService();

        // Normal cases.
        log.info("Route DEPOSIT  -> " + router.route(new PaymentInstruction("DEPOSIT",  rajesh, null, new BigDecimal("50000"))));
        log.info("Route WITHDRAW -> " + router.route(new PaymentInstruction("WITHDRAW", priya, null, new BigDecimal("12000"))));
        log.info("Route TRANSFER -> " + router.route(new PaymentInstruction("TRANSFER", rajesh, priya, new BigDecimal("30000"))));
        log.info("Route UNKNOWN  -> " + router.route(new PaymentInstruction("GIFT",     rajesh, null, new BigDecimal("1000"))));

        // The null-type trap: handled cleanly, no NPE.
        log.info("Route null     -> " + router.route(new PaymentInstruction(null, rajesh, null, new BigDecimal("1000"))));

        // Exhaustive enum switch expression.
        log.info("Tier label HIGH -> " + router.classifyTier(rajesh.getTier()));
    }
}

