enum AccountTier { LOW, MID, HIGH }

// ─── Would be in model/Account.java in a real project ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    private final AccountTier tier;

    Account(String accountId, String holderName, BigDecimal balance, AccountTier tier) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        this.tier = tier;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    AccountTier getTier() { return tier; }
    void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in model/PaymentInstruction.java in a real project ───
class PaymentInstruction {
    private final String type;     // may be null from a buggy upstream
    private final Account from;
    private final Account to;
    private final BigDecimal amount;

    PaymentInstruction(String type, Account from, Account to, BigDecimal amount) {
        this.type = type;
        this.from = from;
        this.to = to;
        this.amount = amount;
    }
    String getType() { return type; }
    Account getFrom() { return from; }
    Account getTo() { return to; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in service/PaymentRouterService.java in a real project ───
class PaymentRouterService {
    private static final Logger log = Logger.getLogger(PaymentRouterService.class.getName());

    // Null guard BEFORE the switch avoids the classic switch(null) NPE.
    String route(PaymentInstruction inst) {
        String type = inst.getType();
        if (type == null) {
            log.warning("Null payment type — rejecting cleanly (no NPE).");
            return "REJECTED_NULL_TYPE";
        }
        // Switch EXPRESSION: arrow arms, no fall-through, returns a value.
        return switch (type) {
            case "DEPOSIT"  -> "CREDIT " + inst.getFrom().getAccountId();
            case "WITHDRAW" -> "DEBIT " + inst.getFrom().getAccountId();
            case "TRANSFER" -> {
                // Block arm with yield — multiple statements then return a value.
                String fromId = inst.getFrom().getAccountId();
                String toId   = inst.getTo().getAccountId();
                yield "MOVE " + fromId + "->" + toId;
            }
            default -> "REJECTED_UNKNOWN";
        };
    }

    // Exhaustive enum switch expression: no default needed because all
    // constants are handled. Adding a new tier would break compilation here.
    String classifyTier(AccountTier tier) {
        return switch (tier) {
            case LOW  -> "BRONZE";
            case MID  -> "SILVER";
            case HIGH -> "GOLD";
        };
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
